"""Generated bytes, decoupled from the process that happens to serve them.

The mesh, the thumbnail and every export are already **content-addressed** —
that was the right call and nothing here changes it. What they were not is
*durable*: all three lived in bounded in-memory LRUs, which has two consequences
a single box hides and a second instance does not.

- **A URL is only good on the instance that made it.** A client is told to cache
  `/api/documents/{id}/artifact/{digest}` forever, and a second API worker has
  never heard of that digest — so the answer is a 404 for a file that exists.
  Content addressing makes that *safe* (it can never be the wrong bytes) without
  making it work.
- **A restart forgets everything generated.** A release package rebuilds every
  slow thing in the system; losing it to a deploy is a fan-out repeated for no
  reason.

So bytes go behind an interface with two adapters. `MemoryStore` is what the old
code was, kept because tests and one-shot tooling want no filesystem at all.
`FilesystemStore` is the default for a real deployment: a shared volume is the
smallest thing that makes a URL valid on every instance and survives a restart.
An object-store adapter (S3, GCS) is the same three methods over a bucket; the
seam is `BlobStore`, and nothing above it knows which one is mounted.

Three rules the interface enforces, each of which was a real bug or one waiting:

- **Authorization is not content addressing** (BLOB-03). A digest is a name, not
  a capability: the store will hand any digest to anyone who asks, and the
  *route* decides whether the caller may read the document it belongs to. That
  is why every key is namespaced by document — a digest alone cannot be walked
  into another tenant's export, and `forget(doc_id)` on deletion is a prefix
  operation rather than a scan.
- **Memory is bounded by bytes, not by entries** (CACHE-03). Forty-eight meshes
  is 15 MB of plates or 4 GB of a shelled body at resolution 256 — the same
  number, two orders of magnitude apart. An entry count is not a memory budget
  and calling it one is how a box OOMs while its cache looks healthy.
- **A missing blob is recoverable, never a broken URL** (BLOB-04). The mesh path
  already re-derives on a miss; this keeps that shape for everything by making
  `get` return `None` rather than raising, so the caller can decide between
  regenerating and 404ing.
"""

from __future__ import annotations

import json
import logging
import os
import re
import shutil
import threading
import time
from pathlib import Path
from typing import Dict, Iterable, NamedTuple, Optional

_LOGGER = logging.getLogger(__name__)


class Blob(NamedTuple):
    """Bytes plus what a caller needs to serve them."""

    payload: bytes
    media_type: str
    filename: str = ""
    #: The fingerprint of the inputs that produced it, when the producer knows
    #: one. Not used for lookup — the digest is the name — but it is what makes
    #: an orphan sweep able to say *why* something is unreachable.
    fingerprint: Optional[str] = None


class Stored(NamedTuple):
    blob: Blob
    bytes: int
    written_at: float


#: A namespace is a document or assembly id, and a digest is a content hash.
#: Both are interpolated into a filesystem path, so both are checked: a `..` in
#: either is a path traversal out of the blob root.
_SAFE = re.compile(r"^[A-Za-z0-9._@:-]{1,128}$")


def _check(namespace: str, digest: str) -> None:
    if not _SAFE.match(namespace or "") or not _SAFE.match(digest or ""):
        raise ValueError(f"unsafe blob key: {namespace!r}/{digest!r}")


class BlobStore:
    """The interface. Three methods do the work; the rest are housekeeping."""

    def put(self, namespace: str, digest: str, blob: Blob) -> None:
        raise NotImplementedError

    def get(self, namespace: str, digest: str) -> Optional[Blob]:
        raise NotImplementedError

    def delete(self, namespace: str, digest: str) -> bool:
        raise NotImplementedError

    def forget(self, namespace: str) -> int:
        """Drop everything under one namespace — a document being deleted."""
        raise NotImplementedError

    def sweep(self, older_than_seconds: float) -> int:
        """Expire blobs nothing has written or read for that long."""
        raise NotImplementedError

    def stats(self) -> dict:
        raise NotImplementedError


# ---------------------------------------------------------------------------
# In memory
# ---------------------------------------------------------------------------

class MemoryStore(BlobStore):
    """A byte-budgeted LRU. What the three separate caches were, unified.

    The budget is the point. `_MESH_CACHE` held 48 entries and `_ARTIFACTS` 64,
    which are memory limits only if every entry is the same size — and they are
    not remotely: the benchmark fixtures alone span a 16 KiB plate mesh and a
    279 MB faceted STEP. Bounding bytes means the cache gives back memory when
    the workload gets heavier, which is when it matters.
    """

    def __init__(self, max_bytes: int, name: str = "memory"):
        self.name = name
        self.max_bytes = max_bytes
        self._entries: "Dict[str, Stored]" = {}
        self._order: list[str] = []
        self._bytes = 0
        self._lock = threading.RLock()
        self.evictions = 0
        self.hits = 0
        self.misses = 0

    @staticmethod
    def _key(namespace: str, digest: str) -> str:
        return f"{namespace}/{digest}"

    def put(self, namespace: str, digest: str, blob: Blob) -> None:
        _check(namespace, digest)
        key = self._key(namespace, digest)
        with self._lock:
            self._drop(key)
            entry = Stored(blob, len(blob.payload), time.time())
            self._entries[key] = entry
            self._order.append(key)
            self._bytes += entry.bytes
            # A single blob larger than the whole budget would evict everything
            # and then itself; keep it, and let the next write settle the total.
            # Refusing it instead would turn a big export into a broken URL.
            while self._bytes > self.max_bytes and len(self._order) > 1:
                self._drop(self._order[0])
                self.evictions += 1

    def get(self, namespace: str, digest: str) -> Optional[Blob]:
        key = self._key(namespace, digest)
        with self._lock:
            entry = self._entries.get(key)
            if entry is None:
                self.misses += 1
                return None
            self.hits += 1
            self._order.remove(key)
            self._order.append(key)
            return entry.blob

    def delete(self, namespace: str, digest: str) -> bool:
        with self._lock:
            return self._drop(self._key(namespace, digest))

    def forget(self, namespace: str) -> int:
        prefix = f"{namespace}/"
        with self._lock:
            keys = [k for k in self._order if k.startswith(prefix)]
            for key in keys:
                self._drop(key)
            return len(keys)

    def sweep(self, older_than_seconds: float) -> int:
        cutoff = time.time() - older_than_seconds
        with self._lock:
            keys = [k for k, e in self._entries.items() if e.written_at < cutoff]
            for key in keys:
                self._drop(key)
            return len(keys)

    def stats(self) -> dict:
        with self._lock:
            return {"backend": "memory", "entries": len(self._entries),
                    "bytes": self._bytes, "max_bytes": self.max_bytes,
                    "evictions": self.evictions, "hits": self.hits,
                    "misses": self.misses}

    def _drop(self, key: str) -> bool:
        entry = self._entries.pop(key, None)
        if entry is None:
            return False
        self._order.remove(key)
        self._bytes -= entry.bytes
        return True


# ---------------------------------------------------------------------------
# On disk
# ---------------------------------------------------------------------------

class FilesystemStore(BlobStore):
    """Bytes on a volume, with a small in-memory cache in front.

    The cache is not an optimisation detail: without it every mesh GET is a disk
    read, and the mesh endpoint is the hottest one in the system. With it, the
    common case is exactly as fast as the old pure-memory store and the *cold*
    case — another instance, or this one after a restart — returns the file
    instead of a 404.

    A blob is two files: the payload, and a small JSON sidecar with the media
    type and filename. Encoding those into the payload file's name was the
    alternative and it does not survive a filename with a slash in it.
    """

    def __init__(self, root: Path, cache_bytes: int, name: str = "filesystem"):
        self.name = name
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        self._cache = MemoryStore(cache_bytes, name=f"{name}-cache")
        self.writes = 0
        self.disk_hits = 0

    def _paths(self, namespace: str, digest: str) -> tuple[Path, Path]:
        _check(namespace, digest)
        folder = self.root / namespace
        return folder / f"{digest}.bin", folder / f"{digest}.json"

    def put(self, namespace: str, digest: str, blob: Blob) -> None:
        payload_path, meta_path = self._paths(namespace, digest)
        payload_path.parent.mkdir(parents=True, exist_ok=True)
        # Written to a temporary name and renamed, so a reader never sees a
        # half-written blob under a digest that promises exactly these bytes.
        # `os.replace` is atomic within a filesystem, which a shared volume is.
        tmp = payload_path.with_suffix(".bin.tmp")
        tmp.write_bytes(blob.payload)
        os.replace(tmp, payload_path)
        meta_path.write_text(json.dumps({
            "media_type": blob.media_type, "filename": blob.filename,
            "fingerprint": blob.fingerprint, "bytes": len(blob.payload)}))
        self.writes += 1
        self._cache.put(namespace, digest, blob)

    def get(self, namespace: str, digest: str) -> Optional[Blob]:
        cached = self._cache.get(namespace, digest)
        if cached is not None:
            return cached
        try:
            payload_path, meta_path = self._paths(namespace, digest)
        except ValueError:
            return None
        if not payload_path.exists():
            return None
        try:
            meta = json.loads(meta_path.read_text()) if meta_path.exists() else {}
            blob = Blob(payload_path.read_bytes(), meta.get("media_type", "application/octet-stream"),
                        meta.get("filename", ""), meta.get("fingerprint"))
        except OSError as exc:  # a volume that vanished is recoverable, not fatal
            _LOGGER.warning("blob %s/%s unreadable: %s", namespace, digest, exc)
            return None
        self.disk_hits += 1
        self._cache.put(namespace, digest, blob)
        return blob

    def delete(self, namespace: str, digest: str) -> bool:
        self._cache.delete(namespace, digest)
        try:
            payload_path, meta_path = self._paths(namespace, digest)
        except ValueError:
            return False
        removed = payload_path.exists()
        payload_path.unlink(missing_ok=True)
        meta_path.unlink(missing_ok=True)
        return removed

    def forget(self, namespace: str) -> int:
        self._cache.forget(namespace)
        try:
            _check(namespace, "x")
        except ValueError:
            return 0
        folder = self.root / namespace
        if not folder.is_dir():
            return 0
        count = len(list(folder.glob("*.bin")))
        shutil.rmtree(folder, ignore_errors=True)
        return count

    def sweep(self, older_than_seconds: float) -> int:
        """Expire blobs nothing has touched, and clear up after deleted documents.

        Retention rather than reference counting. A blob's only referrer is a
        URL somebody may be holding, and there is no way to enumerate those —
        so the honest policy is an age, stated in `DEPLOY.md`, plus a
        regeneration path for anything asked for after it goes.
        """
        cutoff = time.time() - older_than_seconds
        removed = 0
        for payload_path in self.root.glob("*/*.bin"):
            try:
                if payload_path.stat().st_mtime >= cutoff:
                    continue
                payload_path.unlink(missing_ok=True)
                payload_path.with_suffix(".json").unlink(missing_ok=True)
                # And out of the cache in front, or the expired blob goes on
                # being served from memory by the very process that swept it —
                # a retention policy that only applies to the other instances.
                self._cache.delete(payload_path.parent.name, payload_path.stem)
                removed += 1
            except OSError:
                continue
        for folder in self.root.iterdir():
            if folder.is_dir() and not any(folder.iterdir()):
                folder.rmdir()
        return removed

    def stats(self) -> dict:
        total = 0
        count = 0
        for payload_path in self.root.glob("*/*.bin"):
            try:
                total += payload_path.stat().st_size
                count += 1
            except OSError:
                continue
        return {"backend": "filesystem", "root": str(self.root),
                "entries": count, "bytes": total,
                "writes": self.writes, "disk_hits": self.disk_hits,
                "cache": self._cache.stats()}


# ---------------------------------------------------------------------------
# Selection
# ---------------------------------------------------------------------------

def _bytes_env(name: str, default_mb: int) -> int:
    try:
        return int(float(os.getenv(name, "") or default_mb) * 1024 * 1024)
    except ValueError:
        return default_mb * 1024 * 1024


#: The in-memory budget, which is a *memory* budget rather than an entry count.
#: 192 MB is roughly what the three caches it replaces held at their worst case
#: on the fixtures, and small enough for the 512 MB instances this deploys to.
CACHE_BYTES = _bytes_env("FORGE_BLOB_CACHE_MB", 192)

#: How long a generated file stays fetchable. A day: long enough that a package
#: link mailed to a shop still works that afternoon, short enough that a volume
#: does not grow without bound. Everything here regenerates.
RETENTION_SECONDS = float(os.getenv("FORGE_BLOB_RETENTION_HOURS", "24")) * 3600

_STORE: Optional[BlobStore] = None
_STORE_LOCK = threading.Lock()


def store() -> BlobStore:
    """The process's blob store, built on first use.

    `FORGE_BLOB_DIR` selects the filesystem adapter and is what a real
    deployment sets — pointed at a shared volume, it is the smallest change that
    makes a generated URL valid on every instance. Unset, the store is in
    memory, which is what the code did before and what tests want.
    """
    global _STORE
    if _STORE is None:
        with _STORE_LOCK:
            if _STORE is None:
                directory = os.getenv("FORGE_BLOB_DIR", "").strip()
                _STORE = (FilesystemStore(Path(directory), CACHE_BYTES)
                          if directory else MemoryStore(CACHE_BYTES))
                _LOGGER.info("blob store: %s", _STORE.stats().get("backend"))
    return _STORE


def reset_store(new: Optional[BlobStore] = None) -> BlobStore:
    """Swap the store. For tests, and for a deployment that reconfigures at boot."""
    global _STORE
    with _STORE_LOCK:
        _STORE = new
    return store()


# Convenience wrappers, so callers never hold the store object and a swap during
# a test cannot leave one of them writing into the previous one.

def put(namespace: str, digest: str, blob: Blob) -> None:
    store().put(namespace, digest, blob)


def get(namespace: str, digest: str) -> Optional[Blob]:
    return store().get(namespace, digest)


def delete(namespace: str, digest: str) -> bool:
    return store().delete(namespace, digest)


def forget(namespace: str) -> int:
    return store().forget(namespace)


def sweep(older_than_seconds: Optional[float] = None) -> int:
    return store().sweep(RETENTION_SECONDS if older_than_seconds is None
                         else older_than_seconds)


def stats() -> dict:
    return store().stats()


def namespaces_in(paths: Iterable[str]) -> set:
    """The document ids named by a list of blob keys. Used by the orphan sweep."""
    return {p.split("/", 1)[0] for p in paths if "/" in p}
